package com.afterglow.player;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.graphics.*;import java.io.*;
public class QueueSheetChecks extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 void touch(View handle,int action,float y){long now=SystemClock.uptimeMillis();MotionEvent event=MotionEvent.obtain(now,now,action,50,y,0);handle.dispatchTouchEvent(event);event.recycle();}
 public void onStart(){Bundle result=new Bundle();try{MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));for(int i=0;i<100&&a.service==null;i++)Thread.sleep(100);PlaybackService p=a.service;
 runOnMainSync(()->{p.pause(true);p.releasePlayer();p.prefetchSuspended=true;p.queue.clear();p.upcoming.clear();p.index=0;for(int i=0;i<4;i++){Track t=new Track("Queue check "+i,"Original demo","demo","local");p.queue.add(t);if(i>0)p.upcoming.add(t);}a.showQueue();});waitForIdleSync();Thread.sleep(400);
 QueueSheet sheet=(QueueSheet)a.queueRows;Track first=p.upcoming.get(0);runOnMainSync(()->{View card=sheet.cards.get(first);View handle=((android.view.ViewGroup)card).getChildAt(2);int[] location=new int[2];card.getLocationOnScreen(location);touch(handle,MotionEvent.ACTION_DOWN,location[1]+a.dp(30));touch(handle,MotionEvent.ACTION_MOVE,location[1]+a.dp(180));check(sheet.order.indexOf(first)==2,"Drag preview reaches third position");check(p.upcoming.get(0)==first,"No queue mutation before release");touch(handle,MotionEvent.ACTION_UP,location[1]+a.dp(180));check(p.upcoming.get(2)==first,"Release commits reorder");});
 waitForIdleSync();Thread.sleep(200);runOnMainSync(()->{Track t=p.upcoming.get(0);View card=sheet.cards.get(t);View handle=((android.view.ViewGroup)card).getChildAt(2);int[] location=new int[2];card.getLocationOnScreen(location);touch(handle,MotionEvent.ACTION_DOWN,location[1]+a.dp(25));touch(handle,MotionEvent.ACTION_MOVE,location[1]+a.dp(170));touch(handle,MotionEvent.ACTION_CANCEL,location[1]+a.dp(170));check(p.upcoming.get(0)==t,"Cancelled drag preserves queue");check(!a.draggingQueue,"Drag state cleared");});waitForIdleSync();Thread.sleep(300);Bitmap shot=getUiAutomation().takeScreenshot();try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"queue-sheet-check.png"))){shot.compress(Bitmap.CompressFormat.PNG,100,out);}result.putString("result","PASS: handle drag previews, release commits, cancel preserves order; sheet screenshot saved");
 }catch(Throwable e){result.putString("failure",e.toString());}finish(result.containsKey("failure")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
}

